using System;using System.Configuration;using System.Data;using System.Data.SqlClient;using System.Text;using System.Web.UI;namespace ZavaReportDashboard{public partial class Default:Page{protected void Page_Load(object sender,EventArgs e){if(!Request.IsAuthenticated){Response.Redirect("~/Login.aspx?ReturnUrl="+Server.UrlEncode(Request.RawUrl),false);Context.ApplicationInstance.CompleteRequest();return;}if(!IsPostBack){txtStartDate.Text=DateTime.Today.AddDays(-7).ToString("yyyy-MM-dd");txtEndDate.Text=DateTime.Today.ToString("yyyy-MM-dd");RunReports();}}protected void btnRunReports_Click(object sender,EventArgs e){RunReports();}private void RunReports(){DateTime s,e;if(!DateTime.TryParse(txtStartDate.Text,out s)||!DateTime.TryParse(txtEndDate.Text,out e)||e<s){lblStatus.Text="Enter valid date range.";return;}litLoanPortfolioSummary.Text=BuildLoanSummary();BindDelinquency();BindDailyVolume(s,e);ViewState["StartDate"]=s.ToString("yyyy-MM-dd");ViewState["EndDate"]=e.ToString("yyyy-MM-dd");lblStatus.Text="Reports refreshed.";}private string BuildLoanSummary(){var t=new DataTable();using(var c=new SqlConnection(ConfigurationManager.ConnectionStrings["ZavaBankDb"].ConnectionString))using(var cmd=new SqlCommand("SELECT Status, COUNT(*) AS ApplicationCount, ISNULL(SUM(RequestedAmount),0) AS TotalRequested, ISNULL(SUM(ApprovedAmount),0) AS TotalApproved FROM LoanApplications GROUP BY Status ORDER BY Status;",c))using(var a=new SqlDataAdapter(cmd)){c.Open();a.Fill(t);}var b=new StringBuilder();b.Append("<table border='1' cellpadding='4' cellspacing='0' style='border-collapse:collapse;width:100%;background:#fff;'><tr style='background:#e0e7f2;font-weight:bold;'><td>Status</td><td>Applications</td><td>Total Requested</td><td>Total Approved</td></tr>");foreach(DataRow r in t.Rows){b.Append("<tr><td>").Append(Server.HtmlEncode(Convert.ToString(r["Status"]))).Append("</td><td>").Append(Server.HtmlEncode(Convert.ToString(r["ApplicationCount"]))).Append("</td><td>").Append(Server.HtmlEncode(Convert.ToDecimal(r["TotalRequested"]).ToString("C2"))).Append("</td><td>").Append(Server.HtmlEncode(Convert.ToDecimal(r["TotalApproved"]).ToString("C2"))).Append("</td></tr>");}b.Append("</table>");return b.ToString();}private void BindDelinquency(){var t=new DataTable();using(var c=new SqlConnection(ConfigurationManager.ConnectionStrings["ZavaBankDb"].ConnectionString))using(var cmd=new SqlCommand("SELECT TOP 50 PaymentID, ApplicationID, AccountID, DueDate, PaymentAmount, Status FROM LoanPayments WHERE DueDate < GETDATE() AND Status <> 'Paid' ORDER BY DueDate ASC;",c))using(var a=new SqlDataAdapter(cmd)){c.Open();a.Fill(t);}gvDelinquency.DataSource=t;gvDelinquency.DataBind();}private void BindDailyVolume(DateTime s,DateTime e){var t=new DataTable();using(var c=new SqlConnection(ConfigurationManager.ConnectionStrings["ZavaBankDb"].ConnectionString))using(var cmd=new SqlCommand("SELECT CAST(TransactionDate AS DATE) AS TransactionDay, COUNT(*) AS TransactionCount, SUM(ABS(Amount)) AS TotalVolume FROM Transactions WHERE TransactionDate>=@s AND TransactionDate<DATEADD(DAY,1,@e) GROUP BY CAST(TransactionDate AS DATE) ORDER BY TransactionDay;",c))using(var a=new SqlDataAdapter(cmd)){cmd.Parameters.AddWithValue("@s",s);cmd.Parameters.AddWithValue("@e",e);c.Open();a.Fill(t);}gvDailyTransactionVolume.DataSource=t;gvDailyTransactionVolume.DataBind();}}}
